// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAllJobs Every job (admin, after a refresh-on-read)
	// (GET /api/v1/admin/jobs)
	ListAllJobs(ctx context.Context, request ListAllJobsRequestObject) (ListAllJobsResponseObject, error)
	// ReleaseAnyJob Release any user's job (admin)
	// (DELETE /api/v1/admin/jobs/{jobId})
	ReleaseAnyJob(ctx context.Context, request ReleaseAnyJobRequestObject) (ReleaseAnyJobResponseObject, error)
	// ListParkedOutboxMessages Outbox messages that stopped retrying (admin)
	// (GET /api/v1/admin/outbox)
	ListParkedOutboxMessages(ctx context.Context, request ListParkedOutboxMessagesRequestObject) (ListParkedOutboxMessagesResponseObject, error)
	// ProbeProviderCapabilities Let the next use test every unavailable capability again (admin, ADR 0018)
	// (POST /api/v1/admin/providers/{providerId}/probe-capabilities)
	ProbeProviderCapabilities(ctx context.Context, request ProbeProviderCapabilitiesRequestObject) (ProbeProviderCapabilitiesResponseObject, error)
	// ListUnmanagedItems Provider items debroxy does not track (admin, DEC-10)
	// (GET /api/v1/admin/unmanaged-items)
	ListUnmanagedItems(ctx context.Context, request ListUnmanagedItemsRequestObject) (ListUnmanagedItemsResponseObject, error)
	// GetUserSlotQuota A user's slot quota (admin, C14-01)
	// (GET /api/v1/admin/users/{userId}/slot-quota)
	GetUserSlotQuota(ctx context.Context, request GetUserSlotQuotaRequestObject) (GetUserSlotQuotaResponseObject, error)
	// SetSlotQuota Set a user's maximum of charged active jobs (admin)
	// (PUT /api/v1/admin/users/{userId}/slot-quota)
	SetSlotQuota(ctx context.Context, request SetSlotQuotaRequestObject) (SetSlotQuotaResponseObject, error)
	// ListJobs The user's jobs, newest first (after a refresh-on-read)
	// (GET /api/v1/jobs)
	ListJobs(ctx context.Context, request ListJobsRequestObject) (ListJobsResponseObject, error)
	// SubmitJob Submit a source; joins an existing item for the same content (spec §5.5)
	// (POST /api/v1/jobs)
	SubmitJob(ctx context.Context, request SubmitJobRequestObject) (SubmitJobResponseObject, error)
	// ListJobHistory The user's released jobs
	// (GET /api/v1/jobs/history)
	ListJobHistory(ctx context.Context, request ListJobHistoryRequestObject) (ListJobHistoryResponseObject, error)
	// ReleaseJob Release the job; the last release deletes the provider item
	// (DELETE /api/v1/jobs/{jobId})
	ReleaseJob(ctx context.Context, request ReleaseJobRequestObject) (ReleaseJobResponseObject, error)
	// GetJob One job (after a refresh-on-read)
	// (GET /api/v1/jobs/{jobId})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// RenameJob Change the job's display name (owner)
	// (PATCH /api/v1/jobs/{jobId})
	RenameJob(ctx context.Context, request RenameJobRequestObject) (RenameJobResponseObject, error)
	// GetMe The logged-in user and their slot quota (C9-02)
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListProviders The configured providers with their capabilities (C9-03)
	// (GET /api/v1/providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// CheckCachedAvailability Which fingerprints the provider has cached; only torrent fingerprints can be cached
	// (POST /api/v1/providers/{providerId}/cached-availability)
	CheckCachedAvailability(ctx context.Context, request CheckCachedAvailabilityRequestObject) (CheckCachedAvailabilityResponseObject, error)
	// ListHosters The provider's supported web hosters (C9-03)
	// (GET /api/v1/providers/{providerId}/hosters)
	ListHosters(ctx context.Context, request ListHostersRequestObject) (ListHostersResponseObject, error)
	// RefreshProvider Refresh the provider state now (forced; limited per user, ADR 0018)
	// (POST /api/v1/providers/{providerId}/refresh)
	RefreshProvider(ctx context.Context, request RefreshProviderRequestObject) (RefreshProviderResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

